//! The reference world of the world-format tests: a fresh world generated by the vanilla server.
//!
//! The first call starts the vanilla server once (seed 12345, 7x7 chunks force-loaded in each dimension, saved, clean stop) into
//! `run/servers/worldref` and leaves the result there for every later call and test process. Concurrent test
//! processes serialise on a lock file, so exactly one of them generates it.

use std::fs::{self, File};
use std::os::fd::AsRawFd;
use std::path::PathBuf;
use std::time::{Duration, Instant};

use crate::{Error, Result, Server, fail, repo_root};

/// The `world/` directory of the reference world; generated on first use.
///
/// Needs what [`Server::vanilla`] needs (`java`, `ref/server.jar`, `MC_ACCEPT_EULA=1`) unless the world already exists.
/// To rebuild it, delete `run/servers/worldref`.
pub fn worldref() -> Result<PathBuf> {
    let io = |what: &str, e: std::io::Error| Error(format!("{what}: {e}"));
    let servers = repo_root().join("run/servers");
    let dir = servers.join("worldref");
    let world = dir.join("world");
    if world.join("level.dat").is_file() {
        return Ok(world);
    }
    // Take the server permit before the lock, so the process that holds the lock can always start its server.
    let _permit = crate::permit::acquire();
    fs::create_dir_all(&servers).map_err(|e| io("create run/servers", e))?;
    let lock = File::create(servers.join("worldref.lock"))
        .map_err(|e| io("create the worldref lock", e))?;
    // SAFETY: plain syscall on a descriptor this function owns. The lock is released when `lock` drops.
    if unsafe { libc::flock(lock.as_raw_fd(), libc::LOCK_EX) } != 0 {
        return fail(format!(
            "lock the worldref generation: {}",
            std::io::Error::last_os_error()
        ));
    }
    if world.join("level.dat").is_file() {
        return Ok(world);
    }
    let scratch = servers.join(format!("worldref.generating-{}", std::process::id()));
    let _ = fs::remove_dir_all(&scratch);
    let server = Server::vanilla()
        .properties([
            "level-seed=12345",
            "gamemode=creative",
            "difficulty=normal",
            "view-distance=6",
            "simulation-distance=6",
            "online-mode=false",
            "spawn-protection=0",
        ])
        .dir(&scratch)
        .start()?;
    // Force-load the 7x7 chunks around the origin in every dimension and wait until the far corner is in memory:
    // the saved world then has full chunks (and the mobs generated with them) next to the generation-status chunks
    // of the spawn area, like a world somebody played in.
    let dimensions = [
        "minecraft:overworld",
        "minecraft:the_nether",
        "minecraft:the_end",
    ];
    for dimension in dimensions {
        server.cmd(&format!(
            "execute in {dimension} run forceload add -48 -48 48 48"
        ));
    }
    let deadline = Instant::now() + Duration::from_secs(180);
    for dimension in dimensions {
        loop {
            let passed = server.log().matches("Test passed").count();
            server.cmd(&format!("execute in {dimension} if loaded 45 64 45"));
            std::thread::sleep(Duration::from_millis(500));
            if server.log().matches("Test passed").count() > passed {
                break;
            }
            if Instant::now() > deadline {
                return fail(format!(
                    "the force-loaded chunks of {dimension} did not load within 180 s"
                ));
            }
        }
    }
    server.cmd("summon minecraft:pig 3 101 3");
    // Let the world settle for 30 s of game time (fluids flow, light follows) before it is saved.
    server.cmd("tick sprint 600");
    if server.wait_log("Sprint completed", 180).is_none() {
        return fail("the vanilla server did not finish the tick sprint of the reference world");
    }
    server.cmd("save-all flush");
    if server.wait_log("Saved the game", 120).is_none() {
        return fail("the vanilla server did not save the reference world");
    }
    if !server.stop() {
        return fail(
            "the vanilla server did not stop cleanly while generating the reference world",
        );
    }
    drop(server);
    let _ = fs::remove_dir_all(&dir);
    fs::rename(&scratch, &dir)
        .map_err(|e| io("move the generated world into run/servers/worldref", e))?;
    Ok(world)
}
